ottom: env(safe-area-inset-bottom);\n}\n\n.autosave-bar {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 2px 10px;\n  font-size: 11px;\n  background: #f3f2f1;\n  border-bottom: 1px solid #e1dfdd;\n  min-height: 20px;\n}\n\n.autosave-indicator { color: #a19f9d; }\n.autosave-indicator.pending { color: #605e5c; }\n.autosave-indicator.ok { color: #107c10; }\n.autosave-indicator.error { color: #a4262c; font-weight: 600; }\n\n/* ===== Local session list ===== */\n.pwa-section {\n  margin-top: 20px;\n  border-top: 1px solid #e1dfdd;\n  padding-top: 12px;\n}\n\n.pwa-section-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.pwa-section-title {\n  font-size: 13px;\n  font-weight: 600;\n  color: #323130;\n  margin: 0;\n  text-transform: uppercase;\n  letter-spacing: 0.3px;\n}\n\n.pwa-session-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 8px 10px;\n  border: 1px solid #e1dfdd;\n  border-radius: 4px;\n  background: #fff;\n  margin-bottom: 6px;\n}\n\n.pwa-session-row.active { border-color: #0078d4; background: #f3f9fd; }\n\n.pwa-session-info { flex: 1 1 160px; min-width: 0; }\n\n.pwa-session-title {\n  font-size: 13px;\n  font-weight: 600;\n  color: #323130;\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.pwa-session-sub { font-size: 11px; color: #605e5c; margin-top: 2px; }\n\n.pwa-session-actions { display: flex; gap: 6px; flex-shrink: 0; }\n\n.pwa-badge {\n  font-size: 9px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.3px;\n  padding: 1px 5px;\n  border-radius: 3px;\n}\n\n.pwa-badge-ok { background: #dff6dd; color: #107c10; }\n.pwa-badge-warn { background: #fed9cc; color: #a4262c; }\n\n/* ===== Update banner ===== */\n/* An author-origin display rule beats the user-agent [hidden] rule, so the\n