el { margin: 0; }\n.s3-unit-select { width: auto; min-width: 72px; }\n.s3-unit-confirm { display: flex; align-items: center; gap: 4px; font-size: 13px; min-height: 44px; }\n.s3-unit-confirm input { width: 20px; height: 20px; }\n.s3-unit-warn { color: #a4262c; font-size: 12px; margin-bottom: 6px; }\n.s3-file-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }\n\n.s3-viewer-wrap { position: relative; margin-bottom: 12px; }\n.s3-viewer {\n  position: relative;\n  height: min(62vh, 620px);\n  min-height: 300px;\n  border: 1px solid #e1dfdd;\n  border-radius: 4px;\n  overflow: hidden;\n  background: #f3f4f6;\n}\n.s3-canvas { display: block; touch-action: none; }\n.s3-labels { position: absolute; top: 0; left: 0; pointer-events: none; }\n.s3-marker-label {\n  padding: 1px 4px;\n  border-radius: 3px;\n  background: rgba(21, 101, 192, 0.9);\n  color: #fff;\n  font-size: 11px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n.s3-marker-label.active { background: rgba(230, 81, 0, 0.95); }\n.s3-viewer-msg {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #605e5c;\n  font-size: 14px;\n  pointer-events: none;\n}\n.s3-viewer-msg[hidden] { display: none; }\n.s3-view-buttons { position: absolute; top: 8px; right: 8px; display: flex; gap: 4px; }\n.s3-view-buttons .btn { min-width: 40px; min-height: 40px; padding: 4px 8px; }\n\n.s3-section-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 8px 0 6px; }\n.s3-section-head h3 { margin: 0; font-size: 15px; }\n.s3-count { color: #605e5c; font-weight: 400; font-size: 13px; }\n\n.s3-lm-list { display: flex; flex-direction: column; gap: 3px; margin-bottom: 12px; }\n.s3-lm {\n  display: grid;\n  grid-template-columns: 52px 1fr auto auto;\n  align-items: center;\n  gap: 8px;\n  min-height: 44px;\n  padding: 2px 8px;\n  border: 1px solid #e1dfdd;\n  border-radius: 4px;\n  font-size: 13px;\n  cursor: pointer;\n}\n.